/* ============================================================
   FROM HERE ON: design logic (you usually won't need to touch this)
   ============================================================ */

export default function ProductHub() {
  const [query, setQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");

  const categories = useMemo(() => {
    const set = new Set(PRODUCTS.map((p) => p.category));
    return ["All", ...Array.from(set)];
  }, []);

  const spotlight = PRODUCTS.find((p) => p.spotlight);

  const filtered = useMemo(() => {
    return PRODUCTS.filter((p) => {
      const matchesQuery = p.name.toLowerCase().includes(query.toLowerCase());
      const matchesCategory = activeCategory === "All" || p.category === activeCategory;
      return matchesQuery && matchesCategory && !(query === "" && p === spotlight);
    });
  }, [query, activeCategory, spotlight]);

  return (
    <div style={styles.page}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,600;0,9..144,700;1,9..144,500&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        .ph-scroll::-webkit-scrollbar { display: none; }
        .ph-scroll { -ms-overflow-style: none; scrollbar-width: none; }
        .ph-card { transition: transform .18s ease, box-shadow .18s ease; }
        .ph-card:hover { transform: translateY(-3px); box-shadow: 0 10px 24px rgba(28,26,23,0.10); }
        .ph-btn { transition: background .15s ease, transform .12s ease; }
        .ph-btn:hover { background: #1c1a17; }
        .ph-btn:active { transform: scale(0.97); }
        .ph-pill { transition: all .15s ease; }
        .ph-social:hover { border-color: #B8912F; color: #B8912F; }
        .ph-input:focus { outline: none; border-color: #B8912F; }
      `}</style>

      <div style={styles.container}>
        {/* Header */}
        <header style={{ textAlign: "center", padding: "40px 20px 28px" }}>
          <div style={styles.avatarRing}>
            <img src={PROFILE.avatar} alt={PROFILE.name} style={styles.avatarImg} />
          </div>
          <h1 style={styles.name}>{PROFILE.name}</h1>
          <p style={styles.handle}>{PROFILE.handle}</p>
          <p style={styles.bio}>{PROFILE.bio}</p>

          <div style={{ display: "flex", justifyContent: "center", gap: 10, marginTop: 18 }}>
            {PROFILE.socials.map(({ icon: Icon, url, label }) => (
              <a
                key={label}
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                className="ph-social"
                aria-label={label}
                style={styles.socialBtn}
              >
                <Icon size={16} strokeWidth={1.75} />
              </a>
            ))}
          </div>
        </header>

        <div style={styles.hairline} />

        {/* Search */}
        <div style={{ padding: "24px 20px 0" }}>
          <div style={styles.searchWrap}>
            <Search size={16} color="#8B8578" style={{ flexShrink: 0 }} />
            <input
              className="ph-input"
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search products…"
              style={styles.searchInput}
            />
            {query && (
              <button onClick={() => setQuery("")} style={styles.clearBtn} aria-label="Clear search">
                <X size={14} color="#8B8578" />
              </button>
            )}
          </div>
        </div>

        {/* Category pills */}
        <div
          className="ph-scroll"
          style={{
            display: "flex",
            gap: 8,
            padding: "16px 20px 4px",
            overflowX: "auto",
          }}
        >
          {categories.map((cat) => {
            const active = cat === activeCategory;
            return (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className="ph-pill"
                style={{
                  ...styles.pill,
                  background: active ? "#1C1A17" : "#FFFFFF",
                  color: active ? "#F7F1E3" : "#1C1A17",
                  borderColor: active ? "#1C1A17" : "#EAE4D6",
                }}
              >
                {cat}
              </button>
            );
          })}
        </div>

        {/* Spotlight */}
        {spotlight && query === "" && (
          <div style={{ padding: "20px 20px 4px" }}>
            <div style={styles.spotlightLabel}>
              <Star size={11} fill="#B8912F" color="#B8912F" />
              <span>Find of the Week</span>
            </div>
            <a
              href={spotlight.url}
              target="_blank"
              rel="noopener noreferrer"
              className="ph-card"
              style={styles.spotlightCard}
            >
              <img src={spotlight.image} alt={spotlight.name} style={styles.spotlightImg} />
              <div style={{ padding: "16px 18px 18px" }}>
                <div style={styles.eyebrow}>{spotlight.category}</div>
                <div style={styles.spotlightTitle}>{spotlight.name}</div>
                <div className="ph-btn" style={styles.goldBtn}>
                  View on Amazon <ArrowUpRight size={14} />
                </div>
              </div>
            </a>
          </div>
        )}

        {/* Grid */}
        <div style={styles.grid}>
          {filtered.map((p) => (
            <a
              key={p.name}
              href={p.url}
              target="_blank"
              rel="noopener noreferrer"
              className="ph-card"
              style={styles.card}
            >
              <img src={p.image} alt={p.name} style={styles.cardImg} />
              <div style={{ padding: "12px 12px 14px" }}>
                <div style={styles.eyebrow}>{p.category}</div>
                <div style={styles.cardTitle}>{p.name}</div>
                <div className="ph-btn" style={styles.darkBtn}>
                  Shop Now <ArrowUpRight size={12} />
                </div>
              </div>
            </a>
          ))}
        </div>

        {filtered.length === 0 && (
          <p style={{ textAlign: "center", color: "#8B8578", padding: "40px 20px", fontFamily: "Inter" }}>
            No products found. Try a different search term.
          </p>
        )}

        {/* Footer */}
        <footer style={styles.footer}>
          <div style={styles.hairline} />
          <p style={styles.footerText}>
            Contains affiliate links. As an Amazon Associate I earn from qualifying purchases.
          </p>
        </footer>
      </div>
    </div>
  );
}

